import {CutoutPlayer} from './runtime/player.mjs';
import {validate} from './runtime/model.mjs';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
const buttons=[...document.querySelectorAll('button')],keys=new Set(),touch=new Set();let player,baseSpec,attacking=false,run=false,position=.28,hits=0,flash=0,fx=0,last=0,frames=0,fpsAt=0,w=800,h=660;
const status=msg=>$('message').textContent=msg;
function attack(){if(!player||attacking)return;attacking=true;player.play('attack',{restart:true})}
function clearInput(){keys.clear();touch.clear();document.querySelectorAll('[data-move]').forEach(b=>b.classList.remove('active'))}
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch.add(b.dataset.move);b.classList.add('active')});for(const name of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(name,()=>{touch.delete(b.dataset.move);b.classList.remove('active')})}
$('attack').onclick=attack;$('run').onclick=()=>{run=!run;$('run').firstChild.textContent=run?'Chạy: bật ':'Chạy: tắt ';$('run').classList.toggle('active',run)};
$('reset').onclick=()=>{clearInput();position=.28;attacking=false;hits=0;flash=0;player?.play('idle')};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowLeft','ArrowRight',' ','Shift','a','A','d','D'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());if(e.code==='Space'&&!e.repeat)attack()}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInput()});
$('import').onclick=()=>$('file').click();
$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;clearInput();try{if(f.size>30*1024*1024)throw Error('File tối đa 30 MB');const data=JSON.parse(await f.text()),project=validate(data.format==='nightcamp-cutout-export-v1'?data.project:data);const spec=structuredClone(baseSpec);spec.rig=project.rig;spec.parts=project.parts;spec.attachments=project.attachments||[];const slot=$('slot').value;spec.clips[slot]=structuredClone(project.clip);spec.clips[slot].kind=slot==='attack'?'attack':slot==='idle'?'loop':'walk';const defaults=baseSpec.clips.idle.keys[0].P;for(const k of spec.clips[slot].keys)k.P={...defaults,...k.P};const next=await CutoutPlayer.load(spec);player.dispose();player=next;attacking=false;status('Đã nạp '+project.rig+' · clip '+project.clip.name+' → '+slot+' · '+spec.attachments.length+' phụ kiện. Các động tác còn lại dùng mẫu.')}catch(e){status('Không nạp được: '+e.message+' · Ảnh gốc chưa đóng gói cần được copy vào thư mục assets/.')}finally{$('file').value=''}};
function drawScene(dt){
 const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);
 const ground=h*.77,g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#13252d');g.addColorStop(.75,'#264137');g.addColorStop(1,'#1b302b');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
 ctx.fillStyle='#d9ed9c';ctx.globalAlpha=.15;ctx.beginPath();ctx.arc(w*.76,h*.22,38,0,7);ctx.fill();ctx.globalAlpha=1;
 for(let i=0;i<12;i++){const x=(i*97+40)%w,y=ground-140-(i%3)*30;ctx.fillStyle=i%2?'#1c3435':'#193036';ctx.beginPath();ctx.moveTo(x-55,ground);ctx.lineTo(x,y);ctx.lineTo(x+55,ground);ctx.fill()}
 ctx.fillStyle='#253c30';ctx.fillRect(0,ground,w,h-ground);ctx.strokeStyle='#5b715044';ctx.lineWidth=1;for(let y=ground;y<h;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}for(let x=-w;x<w*2;x+=60){ctx.beginPath();ctx.moveTo(w/2+(x-w/2)*.6,ground);ctx.lineTo(x,h);ctx.stroke()}
 const target=w*.76;ctx.save();ctx.translate(target,ground);ctx.rotate(flash>0?Math.sin(flash*65)*.07:0);ctx.fillStyle='#12231c88';ctx.beginPath();ctx.ellipse(0,2,29,8,0,0,7);ctx.fill();ctx.fillStyle=flash>0?'#eac17b':'#9d8161';ctx.fillRect(-7,-120,14,120);ctx.fillRect(-40,-92,80,11);ctx.fillStyle=flash>0?'#f7dfa4':'#b6a182';ctx.beginPath();ctx.arc(0,-124,18,0,7);ctx.fill();ctx.strokeStyle='#66533e';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-78,22,0,7);ctx.stroke();ctx.fillStyle='#c4d2ba';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('HÌNH NỘM',0,24);ctx.restore();
 if(player){const dir=(keys.has('arrowright')||keys.has('d')||touch.has('right')?1:0)-(keys.has('arrowleft')||keys.has('a')||touch.has('left')?1:0),running=run||keys.has('shift');if(!attacking){player.play(dir?(running?'run':'walk'):'idle');if(dir){player.face=dir;position=Math.max(.1,Math.min(.9,position+dir*(running?230:125)*dt/w))}}
 const complete=player.update(dt*+$('speed').value,()=>{fx=.18;const near=Math.abs(position-.76)*w<120;const facing=player.face===Math.sign(.76-position)||Math.abs(.76-position)<.02;if(near&&facing){hits++;flash=.35}});if(attacking&&complete){attacking=false;player.play('idle')}
 const x=position*w,scale=Math.min(2.3,(h*.5)/160);ctx.fillStyle='#10201877';ctx.beginPath();ctx.ellipse(x,ground,28,7,0,0,7);ctx.fill();player.draw(ctx,x,ground,scale,{bones:$('bones').checked,weapon:$('weapon').checked});if(fx>0){ctx.strokeStyle='#f0f5c5';ctx.lineWidth=3;ctx.globalAlpha=fx/.18;ctx.beginPath();ctx.ellipse(x+player.face*52,ground-85,43,55,-.3,-1.3,1.3);ctx.stroke();ctx.globalAlpha=1}
 $('state').textContent={idle:'Đứng · idle',walk:'Di chuyển · walk',run:'Chạy · run',attack:'Đánh · attack'}[player.name];$('hits').textContent=hits+' lần trúng';}
 flash=Math.max(0,flash-dt);fx=Math.max(0,fx-dt);
}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;frames++;if(now-fpsAt>1000){$('fps').textContent=Math.round(frames*1000/(now-fpsAt))+' FPS';frames=0;fpsAt=now}try{drawScene(dt)}catch(e){status('Lỗi hiển thị: '+e.message);console.error(e);return}requestAnimationFrame(frame)}
(async()=>{buttons.forEach(b=>b.disabled=true);try{baseSpec=await fetch('traveler.character.json').then(r=>{if(!r.ok)throw Error('Thiếu nhân vật mẫu');return r.json()});player=await CutoutPlayer.load(baseSpec);status('Sẵn sàng · Traveler đã được nạp từ file nhân vật riêng.');buttons.forEach(b=>b.disabled=false);requestAnimationFrame(frame)}catch(e){status('Lỗi: '+e.message)}})();
